    abandon: "trust abandon --work <id> [--reason <text>]",
    verify: "trust verify --work <id> --task <id> [--claim-token <token>]",
    evidence: "trust evidence --file <path[,path]> [--root <dir>] [--json]",
    features: "trust features --work <id> [--features <json> | --feature <id> [--fail]] --by <verifier> [--claim-token <token>]",
    progress: "trust progress --work <id> --by <actor> --set <json> [--claim-token <token>]",
    intent: "trust intent --work <id> --set <json> [--by <name>]",
    "threat-model": "trust threat-model --work <id> --set <json> [--by <name>]",
    review: "trust review --work <id> [--json]",
    smoke: "trust smoke --work <id> [--command <command>]",
    verdict: "trust verdict --work <id> --verdict <achieved|partial|not_achieved|regressed> --by <name> [--rubric-scores <json>]",
    release: "trust release --work <id> --action <commit|push|pr|merge|deploy> [--execute] [--record-only] --by <name>",
    policy: "trust policy [suggest|approve|revoke] [--id <id>]",
    eval: "trust eval [run|record|status] [--method <name>] [--work <id>] [--dir <dir>] [--status pass|fail]",
    handoff: "trust handoff --work <id> [--drill]",
    inbox: "trust inbox [--all] [--work <id>] [--json]",
    metrics: "trust metrics [--work <id>] [--json]",
    why: "trust why --work <id> [--json]",
    daemon: "trust daemon [--status|--stop|--once|--dry-run|--all] [--limit n] [--interval ms] [--ttl minutes]",
    playbooks: "trust playbooks",
};
function trustHelp(action) {
    return TRUST_HELP[action] ?? `unknown trust action: ${action}\n\`opencode-flow trust --help\` 查看动作列表`;
}
/** 任务图写操作只能由插件工具或人类 CLI 执行；agent session 里的 shell 不能绕过角色权限。 */
function assertOutsideAgentSession(action) {
    if (process.env.OPENCODE_SESSION_ID) {
        throw new Error(`${action} must use the opencode-flow plugin tool inside an agent session, not the CLI`);
    }
}
async function humanDecision(action, context, defaultChoice = "approve", details = "", required = false) {
    const by = arg("--by");
    if (!by) {
        if (required)
            throw new Error("--by required");
        return undefined;
    }
    if (!process.stdin.isTTY || !process.stdout.isTTY) {
        throw new Error("human decision must be confirmed in a TTY");
    }
    if (process.env.OPENCODE_SESSION_ID) {
        throw new Error("human decision must be confirmed outside an agent session");
    }
    const readline = createInterface({ input: process.stdin, output: process.stdout });
    let answer;
    try {
        answer = await readline.question(`确认 ${action}${details ? ` ${details}` : ""}？输入 yes 继续: `);
    }
    finally {
        readline.close();
    }
    if (answer.trim().toLowerCase() !== "yes") {
        throw new Error("human confirmation cancelled");
    }
    const data = JSON.parse(arg("--data") ?? "{}");
    const confirmedAt = new Date().toISOString();
    const choice = arg("--choice") ?? defaultChoice;
    const packageFields = {
        question: details || action,
        options: [
            { id: choice, label: "确认" },
            { id: "reject", label: "取消" },
        ],
        recommended: choice,
        default: choice,
        impact: details || action,
    };
    const rubricScores = arg("--rubric-scores") ? JSON.parse(arg("--rubric-scores")) : undefined;
    return {
        ...data,
        ...packageFields,
        ...(rubricScores ? { rubricScores } : {}),
        by,
        choice,
        source: "human",
        reasonCode: arg("--reason") ?? "other",
        action,
        ...context,
        confirmedAt,
        type: arg("--type") ?? data.type ?? (action === "release:merge" || action === "release:deploy" ? "D-Release" : undefined),
        commandHash: arg("--command-hash") ?? data.commandHash,
        confirmation: { channel: "tty", confirmedAt, action, ...context },
    };
}
export async function main() {
    const command = process.argv[2];
    const root = process.cwd();
    if (command === "--version" || command === "-v") {
        const pkg = JSON.parse(readFileSync(new URL("../package.json", import.meta.url), "utf8"));
        console.log(pkg.version);
        return;
    }
    if (!command || command === "help" || command === "--help") {
        console.log(`opencode-flow <command> [options]

命令：
  init       初始化/升级项目（--force, --no-register, --no-default-agent, --json）
  doctor     检查 Node/OpenCode/git/插件/项目状态
  status     查看当前项目（--all, --json）
  trust      任务图（opencode-flow trust --help）
  worktree   worktree（opencode-flow worktree --help）
  lock       资源锁（opencode-flow lock --help）
  eject      复制 agents/skills/templates
  upgrade    升级 agents/skills/templates
  projects   列出已注册项目

通用：--version, --json`);
        return;
    }
    const simpleHelp = {
        init: "opencode-flow init [--force] [--no-register] [--no-default-agent] [--json]",
        doctor: "opencode-flow doctor [--json]",
        status: "opencode-flow status [--all] [--json]",
        projects: "opencode-flow projects",
        eject: "opencode-flow eject [--force]",
        upgrade: "opencode-flow upgrade [--force]",
    };
    if (process.argv.includes("--help") && simpleHelp[command]) {
        console.log(simpleHelp[command]);
        return;
    }
    if (command === "init") {
        assertOutsideAgentSession("init");
        if (process.argv.includes("--help")) {
            console.log("opencode-flow init [--force] [--no-register] [--no-default-agent] [--json]");
            return;
        }
        if (!isGitRepo(root))
            console.error("提示：当前目录不是 git 仓库；worktree/merge 不可用。");
        const result = ensureProject(root, {
            apply: true,
            force: process.argv.includes("--force"),
            register: !process.argv.includes("--no-register"),
            defaultAgent: !process.argv.includes("--no-default-agent"),
        });
        if (wantsJson())
