        if (existing.some((item) => item.text === entry.text))
            return;
        mkdirSync(join(root, ".opencode-flow"), { recursive: true });
        const lines = [...existing, entry].slice(-50);
        writeFileSync(deferredPath(root), `${lines.map((item) => JSON.stringify(item)).join("\n")}\n`);
    }
