export function runReviewLoop() {
  const results: { name: string; ok: boolean; error?: string }[] = [];
  const test = (name: string, fn: () => void) => {
    try {
      fn();
      results.push({ name, ok: true });
    } catch (error) {
      results.push({ name, ok: false, error: (error as Error)?.stack ?? String(error) });
    }
  };

  test("normalizes findings and generates ids", () => {
    const findings = normalizeReviewFindings([
      { blocking: true, severity: "important", location: "src/a.ts:1", problem: "missing guard", suggestion: "add guard" },
      { blocking: false, severity: "minor", problem: "naming" },
    ]);
    assert.equal(findings.length, 2);
    assert.equal(findings[0]?.id, "F-1");
    assert.equal(findings[0]?.label, "issue");
    assert.equal(findings[1]?.id, "F-2");
  });

  test("rejects incomplete blocking findings", () => {
    assert.throws(
      () => normalizeReviewFindings([{ blocking: true, severity: "critical", problem: "bad" }]),
      /blocking finding requires location/,
    );
    assert.throws(
      () => normalizeReviewFindings([{ blocking: false, severity: "nope", problem: "bad" }]),
      /invalid finding severity/,
    );
    assert.throws(() => normalizeReviewFindings([{ blocking: false, severity: "minor" }]), /problem required/);
  });

  test("recognizes review kinds and blocking findings", () => {
    assert.equal(isReviewKind("review-standards"), true);
    assert.equal(isReviewKind("review-spec"), true);
    assert.equal(isReviewKind("security"), false);
    assert.equal(hasBlockingFindings([{ blocking: false, severity: "minor", problem: "x" }]), false);
    assert.equal(hasBlockingFindings([{ blocking: true, severity: "important", problem: "x" }]), true);
    const brief = formatFindingsBrief(
      [{ id: "F-1", label: "issue", blocking: true, severity: "important", location: "src/a.ts:1", problem: "guard", suggestion: "add" }],
      "blocking findings",
    );
    assert.match(brief, /blocking findings/);
    assert.match(brief, /F-1/);
    assert.match(brief, /src\/a\.ts:1/);
  });

  const passed = results.filter((item) => item.ok).length;
  return { total: results.length, passed, failed: results.length - passed, results };
}
```

