function task(engine: TrustEngine, workItemId: string, key: string) {
  const found = engine.tasks(workItemId).find((item) => item.key === key);
  assert.ok(found, `missing task ${key}`);
  return found;
}

function claimAndClose(engine: TrustEngine, workItemId: string, key: string, input: any = {}) {
  let current = task(engine, workItemId, key);
  if (current.status === "ready" && !current.human) current = engine.claim(current.id, "builder");
  return engine.close(current.id, {
    claimToken: current.claimToken ?? undefined,
    evidence: ["docs/flow/x#abc"],
    ...input,
  });
}

function quickFixToReview(engine: TrustEngine) {
  const { workItem } = engine.createWorkItem({ title: "loop", playbook: "quick-fix", risk: "low" });
  claimAndClose(engine, workItem.id, "fix");
  claimAndClose(engine, workItem.id, "verify");
  return workItem;
}
