    const result = parse(await close.execute({
      taskId: reviewId,
      claimToken: reviewToken,
      evidence: ["docs/flow/x#abc"],
      findings: [{ blocking: true, severity: "important", location: "src/a.ts:1", problem: "guard", suggestion: "add" }],
    }, { agent: "flow-standards-reviewer" }));
    assert.equal(result.status, "blocked");
    const check = new TrustEngine(root);
    try {
      assert.ok(check.tasks(workItemId).some((task) => task.key === "review-standards-rework-1"));
    } finally {
      check.dispose();
    }
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});
```

注意：如果 `flow_trust_close` 依赖 `context.agent`，测试要传 `{ agent: "flow-standards-reviewer" }`；claimToken 从 `engine.claim` 返回后保存到变量，不要依赖环境变量。

